def clear_terminal():
    command = "cls" if os.name == "nt" else "clear"
    try:
        os.system(command)
    except Exception:
        pass

def safe_resize(image, size):
    try:
        return image.resize(size, Image.Resampling.LANCZOS)
    except AttributeError:
        return image.resize(size, Image.LANCZOS)

